layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 38.4px; font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(0, 148, 126); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 148, 126); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 700; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-accent); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
body { background-image: url("{{assets}}/hugo-cuisine-book_c4aa4e9151d0/36129.webp"); background-size: cover; background-position: 50% 50%; background-repeat: repeat-y }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
